using RestSharp;\nusing Serilog;\n\nnamespace AutomationFramework.API.BusinessLogic {\n    public class PetstoreApiHelper {\n        private readonly RestClient _client;\n\n        public PetstoreApiHelper() {\n            _client = new RestClient(\"https://petstore.swagger.io/v2\");\n        }\n\n        public RestResponse CreatePet(object petPayload) {\n            var request = new RestRequest(\"/pet\", Method.POST);\n            request.AddJsonBody(petPayload);\n            var response = _client.Execute(request);\n            Log.Information(\"POST Request sent to /pet with payload: {@PetPayload}\", petPayload);\n            return response;\n        }\n\n        public RestResponse GetPet(int petId) {\n            var request = new RestRequest($\"/pet/{petId}\", Method.GET);\n            var response = _client.Execute(request);\n            Log.Information(\"GET Request sent to /pet/{PetId}\", petId);\n            return response;\n        }\n\n        public RestResponse UpdatePet(object petPayload) {\n            var request = new RestRequest(\"/pet\", Method.PUT);\n            request.AddJsonBody(petPayload);\n            var response = _client.Execute(request);\n            Log.Information(\"PUT Request sent to /pet with payload: {@PetPayload}\", petPayload);\n            return response;\n        }\n\n        public RestResponse DeletePet(int petId) {\n            var request = new RestRequest($\"/pet/{petId}\", Method.DELETE);\n            var response = _client.Execute(request);\n            Log.Information(\"DELETE Request sent to /pet/{PetId}\", petId);\n            return response;\n        }\n    }\n}